/* ================= ФИЛЬМ О ПЕРСОНАЖЕ: Форд, Олдс, Бенц, Майбах, Ланчестер ================= */
SAGA.ford=[
  {id:'ford1',t:'Сарай на Бэгли-авеню',y:1896,when:'start',
   sc:[{img:'Ford Quadricycle',say:'Детройт, 1896 год. В кирпичном сарае за домом пятьдесят восемь по Бэгли-авеню главный инженер электростанции Эдисона Генри Форд ночами собирает свою первую машину: четыре велосипедных колеса и мотор в четыре лошадиные силы.'},
       {say:'Три месяца назад по Детройту уже проехал автомобиль Чарльза Кинга. Форд катил следом на велосипеде и с тех пор почти не спит.'},
       {who:'Клара Форд',line:'Генри, уже три часа ночи. Эдсел опять проснулся от твоего молотка.'},
       {who:'Генри Форд',line:'Ещё немного, Клара. Она почти готова.'},
       {say:'Перед рассветом четвёртого июня квадрицикл готов. И тут выясняется: он шире двери сарая.'}],
   q:'Как вывести машину на улицу?',
   o:[{t:'Взять топор и разбить стену',fx:{rep:2,cash:-150,b:{devTime:[0.92,24]}},res:'Кирпичи летят во двор, и квадрицикл выкатывается в ночь. Друг Форда Джим Бишоп едет впереди на велосипеде и предупреждает извозчиков.'},
      {t:'Разобрать машину и собрать во дворе',fx:{b:{quality:[1.04,36],devTime:[1.06,12]}},res:'Уходит ещё день, зато каждый узел проверен и подтянут. Машина выезжает позже, но ломается реже.'},
      {t:'Дождаться утра и позвать плотника',fx:{cash:-200,b:{lineCap:[1.05,24]}},res:'Плотник прорубает широкие ворота, и сарай становится настоящей мастерской. А соседи так и не узнают, что творится там по ночам.'}]},
  {id:'ford2',t:'Совет Эдисона',y:1899,when:'firstProd',
   sc:[{img:'Henry Ford',say:'Август 1896 года, съезд электрических компаний в Нью-Йорке. Молодой инженер из Детройта рассказывает о своей машине, и его слушает сам Томас Эдисон.'},
       {who:'Томас Эдисон',line:'Молодой человек, вот оно! Ваша машина сама везёт свою силу: ни проводов, ни котла, ни дыма. Продолжайте!'},
       {say:'Через три года начальство предлагает Форду пост управляющего, если он бросит бензиновый мотор. Форд уходит и становится главным инженером Детройтской автомобильной компании.'},
       {who:'Уильям Мёрфи',line:'Генри, акционеры ждут машин на продажу, а не новых чертежей.'},
       {say:'Первый фургон готов, но Форд им недоволен: тяжёлый, капризный, дорогой.'}],
   q:'Выпускать машину сейчас или доводить?',
   o:[{t:'Остановить сборку и доводить',fx:{cash:-600,b:{quality:[1.06,36]}},res:'Форд переделывает машину снова и снова. К началу 1901 года компания закрывается, выпустив около двадцати машин, но Форд теперь точно знает, чего хочет.'},
      {t:'Гнать выпуск, как хотят акционеры',fx:{cash:800,rep:-1,b:{quality:[0.95,24]}},res:'Фургоны уходят к покупателям, деньги — в кассу. Жалобы на поломки приходят почти так же быстро, как чеки.'},
      {t:'Выпускать понемногу и чинить за свой счёт',fx:{cash:-200,rep:2,b:{lineCap:[0.93,18]}},res:'Машин мало, зато каждую механики знают наизусть. Покупатели рассказывают друзьям о фирме, которая не бросает клиента.'}]},
  {id:'ford3',t:'Десять миль в Гросс-Пойнте',y:1901,when:'firstRace',
   // 0.25: «денег нет» — только если у фирмы и правда пусто в кассе
   v:[{if:s=>!sagaPoor(s),sc:[{say:'Октябрь 1901 года, ипподром Гросс-Пойнт под Детройтом. В настоящей истории первая компания Форда к этому дню прогорела, и гоночная машина была его последней надеждой.'},
       {say:'У вашей фирмы дела идут лучше. Но и вам эта гонка нужна: о победителе заговорит вся Америка.'},
       {img:'Alexander Winton',say:'Против него — Александр Уинтон, знаменитый фабрикант и гонщик. Восемь тысяч зрителей не сомневаются, кто победит.'},
       {who:'Спайдер Хафф',line:'Генри, на поворотах я вылезу на подножку и повисну снаружи, чтобы машину не занесло.'},
       {say:'Уинтон уходит вперёд, но к концу гонки его мотор дымит и сдаёт. Форд проносится мимо под рёв трибун.'}]}],
   sc:[{say:'Октябрь 1901 года, ипподром Гросс-Пойнт под Детройтом. Первая компания Форда прогорела, денег нет. Осталась одна надежда — гоночная машина.'},
       {img:'Alexander Winton',say:'Против него — Александр Уинтон, знаменитый фабрикант и гонщик. Восемь тысяч зрителей не сомневаются, кто победит.'},
       {who:'Спайдер Хафф',line:'Генри, на поворотах я вылезу на подножку и повисну снаружи, чтобы машину не занесло.'},
       {say:'Уинтон уходит вперёд, но к концу гонки его мотор дымит и сдаёт. Форд проносится мимо под рёв трибун.'}],
   q:'Как распорядиться славой победителя?',
   o:[{t:'Найти под победу новых инвесторов',fx:{cash:1500,b:{devTime:[1.08,18]}},res:'Уже через месяц появляется «Генри Форд Компани». Но инвесторы хотят машину на продажу, а Форд — гоночную, и вскоре фирма уйдёт от него и станет «Кадиллаком».'},
      {t:'Строить ещё более быструю машину',fx:{cash:-800,mood:8,b:{race:[0.03,24],raceRep:[1.1,24]}},res:'Через год ревущий «999» с Барни Олдфилдом за рулём обгоняет всех. Олдфилд прежде ни разу не водил машину, но Америка запоминает имя Форда.'},
      {t:'Вернуться к машине для покупателей',fx:{rep:1,seg:{people:[1.06,24]},b:{devTime:[0.95,24]}},res:'Приз — хрустальная чаша для пунша — остаётся в доме Фордов. А Генри садится за чертежи машины, которую сможет купить фермер.'}]},
  {id:'ford4',t:'Машина для множества',y:1908,when:['y:1908','sold:2000'],
   sc:[{img:'Ford Model A (1903–04)',say:'В 1903 году дюжина компаньонов вложила в «Форд Мотор» двадцать восемь тысяч долларов. Первые машины продаются хорошо, но Форд мечтает о другом.'},
       {say:'В потайной комнате завода на Пикетт-авеню Форд и его чертёжники рисуют мелом на доске новую машину: высокую, лёгкую, из прочной ванадиевой стали.'},
       {who:'Генри Форд',line:'Я построю автомобиль для великого множества людей. Такой дешёвый, что его сможет купить каждый, кто получает приличное жалованье.'},
       {img:'Ford Model T',say:'Осенью 1908 года «Модель Т» поступает в продажу за восемьсот пятьдесят долларов. Дилеры просят: дайте нам и другие модели.'}],
   q:'Сколько моделей выпускать?',
   o:[{t:'Только одну, для всех',fx:{seg:{people:[1.12,36],middle:[0.9,24]},b:{lineCap:[1.06,36]}},res:'В 1909 году Форд объявляет: отныне только «Модель Т». Позже он пошутит, что покупатель может выбрать любой цвет, если этот цвет чёрный.'},
      {t:'Держать широкую линейку',fx:{seg:{middle:[1.08,24],lux:[1.05,24]},b:{devCost:[1.08,24]}},res:'В каталоге снова модели на любой кошелёк. Дилеры довольны, а заводу приходится перестраиваться под каждую.'},
      {t:'Одна модель, но дорогая и отделанная',fx:{cash:-500,seg:{lux:[1.1,24]},b:{quality:[1.04,36]}},res:'Машина выходит солидной и блестящей. Её покупают врачи и адвокаты, а фермеры по-прежнему запрягают лошадей.'}]},
  {id:'ford5',t:'Пять долларов в день',y:1913,when:'y:1913',
   sc:[{img:'Highland Park Ford Plant',say:'Хайленд-Парк, 1913 год. Шасси тянут тросом вдоль цеха: машина едет к рабочему, а не рабочий к машине. Сборка сокращается с двенадцати с половиной часов до полутора.'},
       {say:'Но люди не выдерживают однообразия. Чтобы держать на заводе четырнадцать тысяч рабочих, за год пришлось нанять больше пятидесяти тысяч.'},
       {who:'Джеймс Кузенс',line:'Генри, давай платить пять долларов в день — вдвое больше, чем где-либо в Детройте.'},
       {who:'Генри Форд',line:'И тогда наши рабочие сами станут нашими покупателями.'}],
   q:'Как удержать людей у конвейера?',
   // 0.25: выбор в фильме и есть решение о зарплате — газета 1914 года второй раз не спрашивает (11c-legal.js: fivedollar)
   o:[{t:'Платить пять долларов в день',fx:{cash:-3000,legal:'fivedollar:lFiveYes',b:{workerEff:[1.12,36]}},res:'Пятого января 1914 года Форд объявляет новую плату, и к воротам сбегаются тысячи — в мороз толпу разгоняют пожарными шлангами. Зато текучесть почти исчезает.'},
      {t:'Ускорить конвейер и нанимать новых',fx:{cash:500,legal:'fivedollar:lFiveNo',b:{lineCap:[1.1,24],workerEff:[0.92,24]}},res:'Линия бежит быстрее, машины дешевеют. Но новички уходят раньше, чем успевают научиться.'},
      {t:'Вернуть бригадную сборку',fx:{legal:'fivedollar:lFiveNo',b:{quality:[1.05,36],lineCap:[0.9,24]}},res:'Опытные бригады собирают машины бережно и не спеша. Люди остаются, но завод выпускает заметно меньше.'}]},
  {id:'ford6',t:'Деньги без банкиров',y:1921,when:'crisis',
   // 0.25: глава помнит, что вы решили в 1916 году (братья Додж: дивиденды или выкуп) и сколько у вас денег.
   // Выкупили доли из кассы и денег хватает — никаких «долгов банкирам»; компаньоны ещё в доле — вопрос о выкупе; в долгах — история как была
   v:[{if:s=>sagaChose(s,'dodgesuit')!=='lDodgeBuy',
     sc:[{img:'Dodge Brothers',say:'Братья Додж выиграли суд: Форд обязан платить компаньонам дивиденды. В настоящей истории он ответил по-своему: в 1919 году выкупил доли всех компаньонов, заняв у банков семьдесят пять миллионов долларов.'},
       {say:'В вашей компании компаньоны по-прежнему в доле. А кризис двадцатого года роняет цены на всё, и на акции тоже.'},
       {img:'Ford River Rouge complex',say:'Покупатели исчезли, у дилеров стоят непроданные машины. На реке Руж растёт завод-гигант, и каждый доллар на счету.'},
       {who:'Эдсел Форд',line:'Отец, компаньоны напуганы кризисом. Сейчас они продадут свои доли дешевле, чем когда-либо.'},
       {who:'Генри Форд',line:'Тогда пусть компания будет нашей. Целиком.'}],
     q:'Выкупить доли компаньонов?',
     o:[{t:'Выкупить на свои деньги',fx:{cashK:-0.25,rep:2,b:{devTime:[0.94,36],devCost:[0.95,36]}},res:'Компания теперь принадлежит одной семье. Никто больше не требует дивидендов, и каждый заработанный доллар идёт в дело.'},
        {t:'Оставить компаньонов в доле',fx:{roy:[0.02,36]},res:'Компаньоны получают свою долю прибыли ещё три года. Денег на новый завод меньше, зато касса цела.'},
        {t:'Не до акций: снизить цены',fx:{seg:{people:[1.12,18]}},res:'В сентябре 1920 года Форд снижает цены почти на треть — раньше всех. Склады пустеют, а покупатели возвращаются первыми.'}]},
    {if:s=>!sagaPoor(s),
     sc:[{img:'Dodge Brothers',say:'Девятнадцатый год. Спор с братьями Додж позади. В настоящей истории Форд выкупил доли всех компаньонов в долг: семьдесят пять миллионов дали банки Бостона и Нью-Йорка.'},
       {say:'А ваша компания расплатилась с компаньонами из своей кассы и никому не должна ни цента. Банкиры с Уолл-стрит напрасно ждут Форда в приёмной.'},
       {img:'Ford River Rouge complex',say:'Двадцатый год приносит кризис: покупатели исчезли, цены падают, у дилеров стоят непроданные машины. А на реке Руж растёт завод-гигант.'},
       {who:'Эдсел Форд',line:'Отец, у нас столько денег, что кризис можно переждать. Но, может быть, его можно обернуть в свою пользу?'},
       {who:'Генри Форд',line:'Деньги в сейфе ничего не делают. Пусть работают на машину.'}],
     q:'Как обернуть кризис в свою пользу?',
     o:[{t:'Снизить цены первыми',fx:{seg:{people:[1.12,18]},b:{matCost:[0.96,24]}},res:'В сентябре 1920 года Форд снижает цены почти на треть — раньше всех. Покупатели возвращаются к нему первыми, а соперникам приходится догонять.'},
        {t:'Купить рудники, леса и железную дорогу',fx:{cashK:-0.08,sup:['mines','timber','rail']},res:'Форд покупает железные рудники, угольные шахты, леса и железную дорогу Детройт — Толидо — Айронтон. Своя руда, свой уголь и свои вагоны: детали дешевеют.'},
        {t:'Купить разорившийся «Линкольн»',fx:{cashK:-0.04,rep:2,seg:{lux:[1.15,36]}},res:'В феврале 1922 года Форд покупает «Линкольн» Генри Лиланда за восемь миллионов долларов. Теперь у Форда есть машина и для миллионеров.'}]}],
   sc:[{img:'Dodge Brothers',say:'После суда с братьями Додж Форд выкупил доли всех компаньонов. Для этого он занял семьдесят пять миллионов долларов, и теперь пришло время платить.'},
       {img:'Ford River Rouge complex',say:'А в стране кризис: покупатели исчезли, склады забиты машинами, на реке Руж стоит недостроенный завод-гигант.'},
       {who:'Эдсел Форд',line:'Отец, нью-йоркские банкиры готовы дать заём. Но хотят посадить своего человека в правление.'},
       {who:'Генри Форд',line:'Пусть поищут другого клиента. Деньги мы найдём у себя.'}],
   q:'Где взять деньги?',
   o:[{t:'Отправить дилерам машины за наличные',fx:{cash:3000,rep:-3,b:{matCost:[0.94,24]}},res:'Форд останавливает завод, распродаёт запасы, урезает расходы и шлёт дилерам машины, которые те обязаны оплатить сразу. К весне долг погашен, но дилеры этого не забудут.'},
      {t:'Взять заём у банкиров',fx:{cash:2500,rep:1,b:{devCost:[1.1,36],devTime:[1.08,24]}},res:'Деньги приходят быстро. Но люди банка сидят на каждом совещании и требуют отчёта за каждый доллар.'},
      {t:'Резко снизить цены',fx:{cash:800,seg:{people:[1.1,18],middle:[0.95,18]}},res:'Ценники падают, и покупатели возвращаются. Прибыли почти нет, зато склады пустеют.'}]},
  {id:'ford7',t:'Последняя Лиззи',y:1927,when:'finale',
   sc:[{img:'Ford Model T',say:'Двадцать шестого мая 1927 года с конвейера сходит пятнадцатимиллионная «Модель Т». Её ласково зовут «Жестянкой Лиззи», но покупатели уходят: у «Шевроле» есть цвета, три передачи и рассрочка.'},
       {who:'Эдсел Форд',line:'Отец, людям нужна новая машина. Я уже нарисовал для неё кузов.'},
       {who:'Генри Форд',line:'Хорошо. Но она должна быть лучше всего, что мы делали.'},
       {img:'Ford Model A (1927–1931)',say:'Заводы встают на полгода, шестьдесят тысяч рабочих ждут. Второго декабря публике показывают новую «Модель А», и посмотреть на неё приходят миллионы.'}],
   q:'Чем закончить эпоху «Модели Т»?',
   o:[{t:'Остановить заводы ради новой машины',fx:{cash:-3000,rep:5,seg:{people:[1.1,24]}},res:'Остановка стоила огромных денег, но «Модель А» стала хитом. Меньше чем за полтора года выпущен миллион машин, и Форд снова обгоняет «Шевроле».'},
      {t:'Выжать из «Лиззи» ещё год',fx:{cash:2000,rep:-3,seg:{people:[0.92,24]}},res:'Заводы работают, касса полна. Но покупатели уходят к соседям, и каждый месяц промедления стоит всё дороже.'},
      {t:'Отдать сыну руль компании',fx:{rep:2,b:{devTime:[0.9,36],quality:[1.03,36]}},res:'Эдсел, президент компании с 1919 года, впервые решает сам. Новые машины выходят красивее, а старик Форд ворчит, но не вмешивается.'}]}
];
SAGA.olds=[
  {id:'olds1',t:'Пар или бензин',y:1896,when:'start',
   sc:[{img:'Ransom E. Olds',say:'Лансинг, штат Мичиган, 1896 год. В мастерской «Олдс и сын» стучат маленькие моторы — их покупают фермеры и мастерские.'},
       {say:'Младший Олдс, Рэнсом, уже строил паровые коляски. Одну из них даже купили для далёкого Бомбея.'},
       {who:'Плини Олдс',line:'Сын, пар мы знаем. А бензин — это взрыв у тебя под сиденьем.'},
       {who:'Рэнсом Олдс',line:'Бензиновый мотор легче и заводится сразу, отец. За ним будущее.'},
       {say:'Летом 1896 года первая бензиновая машина Олдса выезжает на улицы Лансинга.'}],
   q:'На чём строить машины для продажи?',
   o:[{t:'На бензине',fx:{cash:-300,b:{devTime:[0.9,24]}},res:'В 1897 году Олдс с лансингскими дельцами основывает автомобильную компанию. Первые машины собирают почти вручную, но это уже фирма, а не мастерская.'},
      {t:'На паре, как привыкли',fx:{b:{quality:[1.04,24],devTime:[1.1,18]}},res:'Паровая машина тиха и сильна, но котёл тяжёл, а разогрев занимает долгие минуты. Покупатели восхищаются — и ждут.'},
      {t:'Пока делать моторы для других',fx:{cash:800,rep:-1},res:'Моторы расходятся хорошо, касса растёт. Но в Детройте и Кливленде уже строят автомобили, и время работает на них.'}]},
  {id:'olds2',t:'Пожар на Джефферсон-авеню',y:1901,when:'firstProd',
   sc:[{say:'Детройт, 1901 год. Лесопромышленник Сэмюэл Смит вложил в «Олдс Мотор Воркс» огромные деньги. Завод строит опытные машины, одну дороже другой.'},
       {say:'Девятого марта цех охватывает пламя. Огонь пожирает станки и опытные машины.'},
       {img:'Oldsmobile Curved Dash',say:'По легенде, табельщик Джеймс Брэди выкатывает из огня единственную машину — лёгкий двухместный «Кёрвд Дэш» с изогнутым, как у саней, передком.'},
       {who:'Рэнсом Олдс',line:'Всё сгорело, а она уцелела. Значит, её и будем строить: одну модель, дёшево и много.'}],
   q:'Что строить после пожара?',
   o:[{t:'Только маленький «Кёрвд Дэш»',fx:{seg:{people:[1.1,36]},b:{lineCap:[1.08,24],quality:[0.97,24]}},res:'Машина стоит шестьсот пятьдесят долларов, моторы для неё делает Лиланд, коробки передач — братья Додж. В 1901 году собрано четыреста двадцать пять машин, через год — две с половиной тысячи.'},
      {t:'Восстановить всю линейку',fx:{cash:-1500,seg:{middle:[1.08,24],lux:[1.06,24]}},res:'Инженеры по памяти восстанавливают чертежи больших машин. Через год в каталоге снова солидные модели — но и цены под стать.'},
      {t:'Перенести завод в Лансинг',fx:{cash:-600,b:{lineCap:[1.1,36],devTime:[1.08,12]}},res:'Лансинг дарит Олдсу землю под новый завод. Выпуск начинается позже, зато потом идёт широким потоком.'}]},
  {id:'olds3',t:'Восемьсот миль грязи',y:1901,when:'firstRace',
   sc:[{say:'Осень 1901 года. Чтобы привезти машину на выставку в Нью-Йорк, молодой испытатель Рой Чапин едет туда своим ходом из Детройта.'},
       {img:'Oldsmobile Curved Dash',say:'Дороги размыты дождями. Чапин объезжает грязь по бечевнику канала Эри, сам чинит машину и едет семь с половиной дней.'},
       {who:'Рой Чапин',line:'В «Уолдорф-Асторию» меня не пустили через парадный вход — слишком грязный. Зато машина доехала сама!'},
       {say:'В Нью-Йорке это видят все. Торговец Рэй Оуэн готов заказать тысячу машин — неслыханный заказ.'}],
   q:'Принять заказ на тысячу машин?',
   o:[{t:'Принять и строить потоком',fx:{cash:2000,b:{lineCap:[1.1,24],quality:[0.95,24]}},res:'Олдс принимает заказ, и цеха переходят на поточную сборку. В 1904 году «Олдсмобиль» продаёт около пяти тысяч машин — больше всех в Америке.'},
      {t:'Взять половину, но без спешки',fx:{cash:900,rep:2,b:{quality:[1.03,24]}},res:'Торговец ворчит, но соглашается. Машины приходят позже, зато без переделок.'},
      {t:'Отправить Чапина в новые пробеги',fx:{cash:-400,rep:3,mood:6,b:{raceRep:[1.12,24]}},res:'Газеты печатают снимки грязной машины у дверей лучшего отеля Нью-Йорка. Такую рекламу не купишь ни за какие деньги.'}]},
  {id:'olds4',t:'Спор о большой машине',y:1903,when:['y:1903','sold:1000'],
   sc:[{img:'Oldsmobile Curved Dash',say:'1903 год. Маленький «Олдсмобиль» — самая продаваемая машина Америки, завод в Лансинге выпускает их тысячами.'},
       {who:'Фред Смит',line:'Рэнсом, мой отец вложил в этот завод целое состояние. На дешёвых машинах много не заработаешь — нам нужны большие, солидные и дорогие.'},
       {who:'Рэнсом Олдс',line:'Люди ждут машину, которую можно купить. Если мы её бросим, её сделает кто-то другой.'},
       {img:'Ransom E. Olds',say:'Совет директоров на стороне Смитов. Олдса, чьё имя стоит на каждой машине, отстраняют от управления заводом.'}],
   q:'Уступить инвесторам или уйти?',
   // 0.25: это и есть решение по спору со Смитами — газета 1904 года (oldsboard) второй раз не спрашивает
   o:[{t:'Уйти и начать своё дело',fx:{cash:-1000,rep:3,b:{devTime:[0.9,24]}},res:'В 1904 году Олдс уходит и с лансингскими друзьями основывает новую фирму. «Олдсмобиль» без него строит большие машины, и продажи падают.'},
      {t:'Уступить и строить дорогие машины',fx:{cash:1200,legal:'oldsboard:lOldsYes'},res:'В каталоге появляются тяжёлые машины с большими моторами. Выручка с каждой растёт, а покупателей становится меньше.'},
      {t:'Выкупить долю Смитов',fx:{rep:1,legal:'oldsboard:lOldsBuy'},res:'Олдс выкладывает за долю Смитов огромные деньги. Зато завод остаётся верен маленькой машине, а её создатель — хозяином своего имени.'}]},
  {id:'olds5',t:'Три миллиона наличными',y:1908,when:'y:1908',
   sc:[{say:'Новая фирма Олдса хотела носить его имя, но бывшие компаньоны пригрозили судом. Тогда он сложил название из своих инициалов: Р, Е, О — «Рео».'},
       {say:'А Америка распевает песенку «В моём весёлом Олдсмобиле» — о машине, которой он больше не владеет.'},
       {img:'William C. Durant',say:'1908 год. Бенджамин Бриско и Уильям Дюрант задумали собрать крупнейшие марки в один концерн и зовут на переговоры Олдса и Форда.'},
       {who:'Уильям Дюрант',line:'Мистер Олдс, вместе мы будем сильнее всех. Акции нового концерна вас озолотят.'}],
   q:'Войти в большой концерн?',
   o:[{t:'Только за три миллиона наличными',fx:{cash:-200,rep:2,b:{devTime:[0.93,24]}},res:'Форд и Олдс требуют по три миллиона наличными, банкиры отказываются, и «Рео» остаётся независимой. Дюрант создаёт «Дженерал Моторс» без них — и в том же году покупает «Олдсмобиль».'},
      {t:'Войти в концерн за акции',fx:{cash:2500,rep:-2,b:{devCost:[0.92,36],devTime:[1.08,36]}},res:'Олдс получает пакет акций и место в совете. Деньги концерна кстати, но теперь каждое решение приходится согласовывать в Нью-Йорке.'}]},
  {id:'olds6',t:'Скоростной фургон',y:1917,when:'war',
   sc:[{say:'1915 год. «Рео» выпускает лёгкий и быстрый грузовичок — «Спид Вэгон», «скоростной фургон».'},
       {who:'Рэнсом Олдс',line:'Фермеру и лавочнику не нужна пятитонная махина. Им нужен фургон, который бегает как легковая машина и стоит не дороже её.'},
       {img:'Liberty truck',say:'В 1917 году Америка вступает в войну. Армии нужны тысячи грузовиков, а сталь и рабочие руки теперь на вес золота.'},
       {who:'Ричард Скотт',line:'Мистер Олдс, легковые почти не покупают, а за грузовиками очередь. Может, отдать под них весь завод?'}],
   q:'Что строить в годы войны?',
   o:[{t:'Отдать завод грузовикам',fx:{cash:1500,seg:{truck:[1.15,36],people:[0.92,24]}},res:'Грузовички «Рео» разъезжаются по фермам, складам и стройкам. После войны «Спид Вэгон» станет одним из самых известных грузовиков Америки.'},
      {t:'Держаться легковых машин',fx:{rep:1,seg:{middle:[1.06,24]},b:{matCost:[1.08,24]}},res:'Сталь дорожает, покупателей мало, но марка не исчезает из витрин. Когда война кончится, покупатели вспомнят, кто их не бросил.'},
      {t:'Выполнять военные заказы',fx:{cash:2500,rep:-1,b:{workerEff:[1.05,24],quality:[0.97,24]}},res:'Армейские заказы идут по твёрдой цене, завод работает в три смены. Но спешка сказывается на отделке.'}]},
  {id:'olds7',t:'Башня над Лансингом',y:1929,when:'finale',
   sc:[{img:'Ransom E. Olds',say:'Лансинг, 1929 год. Олдсу шестьдесят пять. Его имя носят две марки: «Олдсмобиль», давно принадлежащий «Дженерал Моторс», и «Рео», сложенная из его инициалов.'},
       {say:'Он построил в городе отель, подарил колледжу инженерный корпус, а рабочим «Рео» — клуб.'},
       {img:'Roaring Twenties',say:'А Америка веселится: джаз, чарльстон, и акции дорожают каждый день.'},
       {who:'Ричард Скотт',line:'Мистер Олдс, вся страна скупает акции. Может, и нам пустить свободные деньги на биржу?'},
       {who:'Рэнсом Олдс',line:'Я верю в то, что можно потрогать руками: в заводы, дома и машины.'}],
   q:'Куда вложить состояние в 1929 году?',
   o:[{t:'Строить в Лансинге',fx:{cash:-2000,rep:5},res:'Над Лансингом поднимается башня Олдса — самое высокое здание города. Когда в октябре рухнет биржа, стройка даст людям работу.'},
      {t:'Вложить в роскошную новую модель',fx:{cash:-1500,seg:{lux:[1.12,24]}},res:'Инженеры «Рео» готовят роскошную восьмицилиндровую машину. Она удалась, но выйдет в самый неудачный момент — в разгар Великой депрессии.'},
      {t:'Держать деньги наготове',fx:{cash:1500,rep:-1},res:'Олдс не играет на бирже, и октябрьский крах почти не задевает его. Но и городу от этих денег ни тепло ни холодно.'}]}
];
SAGA.benz=[
  {id:'benz1',t:'Экипаж с газовым двигателем',y:1886,when:'start',
   sc:[{img:'Benz Patent-Motorwagen',say:'Мангейм, 1886 год. Двадцать девятого января Карл Бенц получает патент на «экипаж с газовым двигателем»: три колеса, мотор под сиденьем, меньше одной лошадиной силы.'},
       {img:'Carl Benz',say:'Летом он впервые выезжает на Рингштрассе на глазах у публики. Прохожие шарахаются, лошади встают на дыбы.'},
       {who:'Макс Розе',line:'Карл, фирму кормят газовые моторы для мастерских. А твоя коляска только пугает лошадей.'},
       {who:'Берта Бенц',line:'Я вложила в твоё дело своё приданое, Карл. Не для того, чтобы ты всю жизнь строил моторы для чужих станков.'}],
   q:'Во что вложить доходы от газовых моторов?',
   o:[{t:'В самодвижущийся экипаж',fx:{cash:-400,b:{devTime:[0.88,24]}},res:'Бенц строит вторую и третью модель. Компаньоны Розе и Эсслингер через несколько лет уйдут из фирмы, зато у Бенца будет машина, которую можно продавать.'},
      {t:'В газовые моторы, как хотят компаньоны',fx:{cash:900,b:{devTime:[1.1,18]}},res:'Моторы расходятся хорошо, касса полна. А коляска пылится в углу мастерской.'},
      {t:'Найти новых компаньонов с деньгами',fx:{cash:500,rep:-1,b:{devCost:[0.92,24]}},res:'Новые пайщики дают деньги на опыты, но требуют отчёта за каждую марку. Работа идёт, хотя и под чужим присмотром.'}]},
  {id:'benz2',t:'Сто шесть километров',y:1888,when:'firstProd',
   sc:[{img:'Carl Benz',say:'Август 1888 года. Машины Бенца почти никто не покупает: кто рискнёт ехать в экипаже, который дальше окраины не бывал?'},
       {img:'Benz Patent-Motorwagen',say:'На рассвете Берта Бенц тайком от мужа выкатывает машину и с сыновьями Ойгеном и Рихардом едет к матери в Пфорцхайм.'},
       {say:'Засорилась топливная трубка — Берта прочищает её шляпной булавкой, подвязкой изолирует провод. Кончился бензин — она покупает лигроин в аптеке Вислоха. Сапожник набивает кожу на тормозные колодки.'},
       {who:'Берта Бенц',line:'Карл, мы доехали! Только в гору пришлось толкать. Машине нужна ещё одна, низкая передача.'}],
   q:'Что делать после поездки Берты?',
   o:[{t:'Добавить передачу для подъёмов',fx:{b:{quality:[1.05,36],devTime:[1.06,12]}},res:'Бенц ставит низшую передачу, а сапожная кожа становится первыми тормозными накладками. Осенью машина получает золотую медаль на выставке в Мюнхене.'},
      {t:'Рассказать о поездке всем газетам',fx:{cash:-300,rep:3,b:{adEff:[1.1,24]}},res:'Все говорят о женщине, проехавшей сто шесть километров без лошади. Покупатели впервые спрашивают о цене.'},
      {t:'Отвезти машину в Париж, к агенту',fx:{cash:600,seg:{lux:[1.08,24]}},res:'Парижский агент Эмиль Роже берётся продавать машины Бенца во Франции — там автомобиль ждут охотнее, чем дома.'}]},
  {id:'benz3',t:'Снег над Чикаго',y:1895,when:'firstRace',
   sc:[{img:'Benz Velo',say:'1895 год. Фирма Бенца строит «Вело» — лёгкую четырёхколёсную машину, первую в мире, которую выпускают сериями.'},
       {img:'Chicago Times-Herald race',say:'Чикаго, День благодарения. По заснеженным улицам стартуют шесть машин, среди них — машины системы Бенца.'},
       {who:'Чарльз Кинг',line:'Мюллер потерял сознание! Держите его, я сам поведу машину до финиша.'},
       {say:'Первым приходит американец Фрэнк Дурьеа. «Бенц» Оскара Мюллера — вторым: из шести машин до финиша добрались только две.'},
       {who:'Карл Бенц',line:'Машина должна довезти, а не обогнать. Пусть гоняются другие.'}],
   q:'Гоняться или строить надёжные машины?',
   o:[{t:'Строить надёжные, а не быстрые',fx:{seg:{middle:[1.05,24]},b:{quality:[1.05,36],raceRep:[0.9,24]}},res:'«Вело» расходятся по всей Европе, и к 1900 году фирма Бенца — крупнейший автозавод мира. Но быстрые машины соперников уже наступают на пятки.'},
      {t:'Выставлять машины на гонки',fx:{cash:-600,mood:6,b:{race:[0.03,24],raceRep:[1.12,24]}},res:'Машины Бенца выходят на старт по всей Европе. Побеждают они нечасто, но публика запоминает марку.'},
      {t:'Продать лицензию американцам',fx:{cash:1200,rep:-1},res:'Заокеанские мастерские строят копии, и деньги за лицензию приходят исправно. Правда, копии не всегда так же хороши, как оригинал.'}]},
  {id:'benz4',t:'Француз в Мангейме',y:1903,when:'y:1903',
   sc:[{img:'Mercedes 35 hp',say:'1903 год. Низкий и быстрый «Мерседес» из Каннштатта уводит у Бенца покупателей. Продажи фирмы падают год от года.'},
       {who:'Юлиус Ганс',line:'Господин Бенц, клиенты хотят машины, как у «Мерседеса». Мы пригласили француза Барбару с его инженерами.'},
       {img:'Carl Benz',who:'Карл Бенц',line:'В моей фирме чертят чужие люди, а мои машины называют устаревшими. Я в этом участвовать не буду.'},
       {say:'Сыновья Ойген и Рихард встают на сторону отца. В правлении спорят до хрипоты.'}],
   q:'Как ответить на французские чертежи?',
   // 0.25: это и есть решение по спору с советом директоров — газета (benzboard) второй раз не спрашивает
   o:[{t:'Уйти из фирмы, но не отступиться',fx:{cash:-800,rep:2,legal:'benzboard:lBenzOld',b:{quality:[1.04,36]}},res:'Бенц уходит из правления. Машины француза успеха не приносят, Барбару вскоре уезжает, а в 1906 году Карл с сыновьями открывает семейную фирму в Ладенбурге.'},
      {t:'Принять француза и учиться',fx:{legal:'benzboard:lBenzNew',b:{devTime:[0.88,24],quality:[0.97,24]}},res:'Новые машины рождаются быстро, мотор теперь стоит впереди. Но старые мастера ворчат, а покупатели путаются в моделях.'},
      {t:'Устроить конкурс чертежей',fx:{cash:-500,b:{devTime:[0.94,24],devCost:[1.06,24]}},res:'Свои и французские инженеры соревнуются проектами. Лучшие идеи идут в дело, хотя конкурс обходится недёшево.'}]},
  {id:'benz5',t:'Молния',y:1909,when:'y:1909',
   sc:[{img:'Blitzen Benz',say:'1909 год. Инженеры фирмы «Бенц» строят гоночного гиганта с мотором больше двадцати одного литра — «Блитцен-Бенц», «Молнию». В Бруклендсе француз Виктор Эмери разгоняет её быстрее двухсот километров в час.'},
       {say:'Карл Бенц давно не руководит фирмой, но она носит его имя. Из Ладенбурга он следит за каждым рекордом.'},
       {who:'Эрни Моросс',line:'Продайте мне эту машину. В Америке за её рёв будут платить тысячи зрителей.'},
       {who:'Ойген Бенц',line:'Отец, это наша фамилия. Пусть весь мир услышит слово «Бенц».'}],
   q:'Продать «Молнию» американцам?',
   o:[{t:'Продать и отправить за океан',fx:{cash:1500,rep:3,mood:-5},res:'В 1910 году Барни Олдфилд разгоняет «Молнию» на пляже Дейтоны до двухсот одиннадцати километров в час, а через год Боб Бёрман — до двухсот двадцати восьми. Ни один самолёт тогда не летает так быстро.'},
      {t:'Оставить заводской команде',fx:{cash:-800,mood:8,b:{race:[0.04,24],drvFee:[1.1,24]}},res:'«Молния» колесит по трассам Европы под заводским флагом. Гонщики рвутся за её руль, но и платить им приходится больше.'},
      {t:'Разобрать и изучить',fx:{rep:-1,b:{devTime:[0.92,24],quality:[1.03,24]}},res:'Инженеры измеряют каждую деталь рекордного мотора. Уроки «Молнии» переходят в обычные машины, а публика так и не видит её на пляже.'}]},
  {id:'benz6',t:'Моторы для фронта',y:1914,when:'war',
   sc:[{img:'World War I',say:'Август 1914 года. Германия воюет. Рабочих фирмы «Бенц» забирают в армию, легковые машины реквизируют для штабов.'},
       {say:'Армии нужны авиамоторы и грузовики. Моторы «Бенц» поднимают в небо немецкие самолёты.'},
       {say:'Карлу Бенцу семьдесят. Он давно отошёл от дел фирмы, носящей его имя, и живёт с Бертой в Ладенбурге.'},
       {who:'Берта Бенц',line:'Карл, мы строили машину, чтобы люди ездили в гости. А теперь она возит снаряды.'},
       {who:'Карл Бенц',line:'Машина не выбирает, что везти, Берта. Выбирают люди.'}],
   q:'Чем заняться заводу в войну?',
   o:[{t:'Строить авиамоторы для армии',fx:{cash:2000,rep:-1,b:{quality:[1.04,36],lineCap:[0.92,24]}},res:'Авиамоторы учат мастеров работать с точностью до сотых долей миллиметра. После войны этот опыт пригодится в автомобилях.'},
      {t:'Строить грузовики для фронта',fx:{cash:1500,seg:{truck:[1.15,36],people:[0.9,24]}},res:'Грузовики «Бенц» из Гаггенау тянут снаряды и хлеб по раскисшим дорогам. После войны многие из них вернутся на мирные улицы.'},
      {t:'Беречь мастеров для мирных машин',fx:{cash:-1000,rep:2,b:{workerEff:[1.06,36]}},res:'Часть мастеров удаётся оставить у станков. Когда наступит мир, они первыми вернутся к легковым машинам.'}]},
  {id:'benz7',t:'Звезда в лавровом венке',y:1929,when:'finale',
   // 0.25: от слияния 1926 года (газета dbmerge) отказались — фильм не рассказывает про общую звезду на ваших радиаторах
   v:[{if:s=>sagaChose(s,'dbmerge')==='lDbNo',t:'Своей дорогой',
     sc:[{img:'Hyperinflation in the Weimar Republic',say:'После войны Германия пережила нищету и инфляцию: в 1923 году буханка хлеба стоила миллиарды марок. Поодиночке автозаводы выживают с трудом.'},
       {img:'Mercedes-Benz',say:'В 1926 году «Даймлер» звал фирму Бенца под одну звезду. В настоящей истории так и вышло: родилась марка «Мерседес-Бенц». А ваша фирма ответила отказом и идёт своей дорогой.'},
       {say:'Ладенбург, весна 1929 года. Восьмидесятичетырёхлетний Карл Бенц смотрит в окно на проезжающие машины. Рядом, как и сорок лет назад, Берта.'},
       {img:'Carl Benz',who:'Карл Бенц',line:'Любовь к изобретательству не умирает никогда.'}],
     o:[{t:'Передать дело ученикам',fx:{cash:-500,rep:4,b:{quality:[1.04,36]}},res:'Четвёртого апреля 1929 года Карла Бенца не стало. Его ученики ведут фирму дальше, а Берта доживёт до девяноста пяти лет.'},
        {t:'Сохранить семейную фирму сыновей',fx:{cash:1000,rep:1,seg:{lux:[1.08,24]}},res:'Мастерская в Ладенбурге остаётся семейной. Машин она выпускает немного, но каждая помнит руку мастера.'},
        {t:'Открыть музей первых машин',fx:{cash:-800,rep:3,b:{adEff:[1.1,24]}},res:'Первый «Моторваген» встаёт под стекло, и к нему едут школьники со всей страны. Молодые инженеры видят, с чего всё началось.'}]}],
   sc:[{img:'Hyperinflation in the Weimar Republic',say:'После войны Германия пережила нищету и инфляцию: в 1923 году буханка хлеба стоила миллиарды марок. Поодиночке автозаводы не выживают.'},
       {img:'Mercedes-Benz',say:'В 1926 году «Бенц и Ко» и «Даймлер» объединяются. На радиаторах теперь трёхлучевая звезда Даймлера в лавровом венке Бенца.'},
       {say:'Ладенбург, весна 1929 года. Восьмидесятичетырёхлетний Карл Бенц смотрит в окно на проезжающие машины. Рядом, как и сорок лет назад, Берта.'},
       {img:'Carl Benz',who:'Карл Бенц',line:'Любовь к изобретательству не умирает никогда.'}],
   q:'Что оставить после себя?',
   o:[{t:'Передать дело объединённой фирме',fx:{cash:-500,rep:4,b:{quality:[1.04,36]}},res:'Четвёртого апреля 1929 года Карла Бенца не стало. Марка «Мерседес-Бенц» переживёт век, а Берта доживёт до девяноста пяти лет.'},
      {t:'Сохранить семейную фирму сыновей',fx:{cash:1000,rep:1,seg:{lux:[1.08,24]}},res:'Мастерская в Ладенбурге остаётся семейной. Машин она выпускает немного, но каждая помнит руку мастера.'},
      {t:'Открыть музей первых машин',fx:{cash:-800,rep:3,b:{adEff:[1.1,24]}},res:'Первый «Моторваген» встаёт под стекло, и к нему едут школьники со всей страны. Молодые инженеры видят, с чего всё началось.'}]}
];
SAGA.maybach=[
  {id:'maybach1',t:'Теплица в Каннштатте',y:1882,when:'start',
   sc:[{img:'Wilhelm Maybach',say:'Вильгельм Майбах рано осиротел и вырос в приюте в Ройтлингене. Там его заметил Готлиб Даймлер, и с тех пор они работают вместе.'},
       {say:'1882 год. В саду виллы Даймлера в Каннштатте стоит теплица, переделанная в мастерскую. По ночам оттуда доносятся стук и звон металла.'},
       {who:'Садовник',line:'Господин полицейский, они там что-то чеканят по ночам. Не иначе фальшивые монеты!'},
       {say:'Полиция врывается в теплицу и находит только детали мотора. Через три года здесь заработает лёгкий быстроходный мотор, похожий на напольные часы.'}],
   q:'Как работать дальше?',
   o:[{t:'По-прежнему в тайне',fx:{rep:-1,b:{devTime:[0.88,24]}},res:'Слухи в Каннштатте не стихают, зато никто не мешает. В 1885 году мотор ставят на деревянный «Райтваген» — первый в мире мотоцикл, а в 1886 году — в карету.'},
      {t:'Показать мотор властям и соседям',fx:{rep:2,b:{devTime:[1.06,12]}},res:'Полицейские уходят, качая головами, а по городу идёт слух о двух чудаках с мотором без лошади. Заказчики начинают стучаться в калитку.'},
      {t:'Снять настоящую мастерскую',fx:{cash:-400,b:{lineCap:[1.06,24],quality:[1.02,24]}},res:'Теплицу сменяет просторный цех со станками. Работа идёт ровнее, хотя деньги Даймлера тают быстрее.'}]},
  {id:'maybach2',t:'Пороховые компаньоны',y:1890,when:'firstProd',
   sc:[{img:'Daimler-Motoren-Gesellschaft',say:'1890 год. Рождается «Даймлер Моторен Гезельшафт». Деньги дают пороховой фабрикант Макс Дуттенхофер и промышленник Вильгельм Лоренц.'},
       {say:'А во Францию уже уезжают моторы Даймлера и Майбаха: по лицензии их ставят на свои машины Панар и Пежо.'},
       {who:'Макс Дуттенхофер',line:'Автомобили — забава. Нам нужны моторы для лодок, насосов и мастерских: их покупают уже сегодня.'},
       {say:'Майбаху, придумавшему половину этих моторов, предлагают место без права голоса и скромное жалованье.'},
       {who:'Готлиб Даймлер',line:'Вильгельм, не уходи далеко. Я буду платить тебе сам, и мы продолжим.'}],
   q:'Принять место в новой фирме?',
   o:[{t:'Уйти и работать с Даймлером на свои',fx:{cash:-600,b:{devTime:[0.88,24],quality:[1.03,24]}},res:'В 1891 году Майбах уходит из фирмы. Вскоре они с Даймлером обосновываются в пустующем отеле «Герман» — там родятся их лучшие моторы.'},
      {t:'Подписать и строить то, что продаётся',fx:{cash:1000,b:{lineCap:[1.06,24],devTime:[1.1,24]}},res:'Моторы для лодок и насосов уходят покупателям один за другим. Но на новые идеи не остаётся ни времени, ни права голоса.'}]},
  {id:'maybach3',t:'Отель «Герман»',y:1895,when:'firstRace',
   sc:[{say:'Каннштатт, пустующий отель «Герман». В его залах Майбах и Даймлер строят моторы на свои деньги.'},
       {say:'В 1893 году Майбах придумывает карбюратор с форсункой: бензин распыляется в воздухе, как духи из флакона. Следом рождается мотор «Феникс».'},
       {img:'Paris–Bordeaux–Paris',say:'А во Франции машины с моторами системы Даймлера выигрывают первые гонки: Париж — Руан, Париж — Бордо — Париж.'},
       {who:'Фредерик Симмс',line:'Господа, английские деньги придут в фирму, только если вы оба вернётесь.'}],
   q:'Вернуться в фирму, которая вас выставила?',
   o:[{t:'Вернуться вместе с «Фениксом»',fx:{cash:1200,rep:2,b:{devTime:[1.05,12]}},res:'В 1895 году Даймлер и Майбах возвращаются, Майбах становится главным инженером. «Феникс» расходится по всему миру, но старые обиды никуда не делись.'},
      {t:'Продать патенты на сторону',fx:{cash:2500,rep:-2,b:{devTime:[1.08,24]}},res:'Англичане и французы платят щедро. Но мотор, придуманный в Каннштатте, теперь прославляет чужие марки.'},
      {t:'Остаться вольными изобретателями',fx:{cash:-700,b:{devTime:[0.88,24],quality:[1.03,24]}},res:'Отель «Герман» гудит от новых идей, но денег всё меньше. Каждый месяц свободы оплачен из кармана Даймлера.'}]},
  {id:'maybach4',t:'Имя девочки',y:1900,when:'y:1900',
   sc:[{say:'Март 1900 года. Умирает Готлиб Даймлер. Майбах остаётся один на один с правлением.'},
       {img:'Emil Jellinek',who:'Эмиль Еллинек',line:'Мне нужна машина длинная, низкая и мощная — лучшая в мире. Я беру тридцать шесть штук, но она будет носить имя моей дочери.'},
       {say:'Майбах ставит мотор в тридцать пять сил на штампованную стальную раму и придумывает сотовый радиатор. Имя машине — «Мерседес».'},
       {img:'Mercedes 35 hp',say:'Весной 1901 года «Мерседес» выигрывает всё на гонках в Ницце. «Мы вступили в эру Мерседеса», — объявляет секретарь французского автоклуба.'}],
   q:'Принять заказ Еллинека?',
   o:[{t:'Строить машину его мечты',fx:{rep:4,legal:'jellinek:lJelYes',b:{devCost:[1.12,24]}},res:'«Мерседес» становится образцом для всех, а французы называют Майбаха королём конструкторов. Вскоре имя девочки получит вся марка.'},
      {t:'Строить привычные надёжные машины',fx:{cash:1200,rep:-1,legal:'jellinek:lJelNo',b:{quality:[1.03,24]}},res:'Старые модели продаются ровно и без хлопот. Но соперники уже ищут своего Еллинека.'},
      {t:'Взять заказ, но под своей маркой',fx:{cash:600,rep:2,seg:{lux:[1.06,24]}},res:'Машина выходит под привычной маркой фирмы. Еллинек обижен и заказывает меньше, но имя основателя остаётся на радиаторе.'}]},
  {id:'maybach5',t:'Моторы для неба',y:1908,when:['y:1908','sold:1000'],
   sc:[{say:'1907 год. В фирме Даймлера Майбаха оттесняют от дел, и он уходит. Ему за шестьдесят, и кажется, что всё позади.'},
       {img:'Zeppelin LZ 1',say:'Граф Фердинанд фон Цеппелин строит дирижабли с 1900 года. Летом 1908 года его новый корабль сгорает у Эхтердингена, и вся Германия собирает деньги на следующий.'},
       {who:'Граф Цеппелин',line:'Господин Майбах, моим кораблям нужны моторы, которые не подведут над облаками.'},
       {who:'Карл Майбах',line:'Отец, давай строить их вместе. Я поведу завод, а ты — чертежи.'}],
   q:'Уйти в небо или остаться на земле?',
   o:[{t:'Строить моторы для дирижаблей',fx:{cash:-500,b:{quality:[1.06,36],lineCap:[0.92,24]}},res:'В 1909 году появляется фирма авиамоторов Цеппелина и Майбахов, её ведёт Карл Майбах. Моторы, работающие сутками, учат делать вещи на века.'},
      {t:'Вернуться к автомобилям',fx:{rep:1,seg:{lux:[1.08,24]},b:{devTime:[0.94,24]}},res:'Майбах снова чертит легковые машины. Богатые клиенты довольны, но небо достаётся другим.'},
      {t:'Отдать дела сыну и отдохнуть',fx:{cash:800,b:{devTime:[1.05,24],workerEff:[1.04,24]}},res:'Карл берёт дела на себя, отец лишь изредка заглядывает в цех. Работа идёт спокойнее, но без прежних озарений.'}]},
  {id:'maybach6',t:'С неба на дорогу',y:1921,when:'crisis',
   sc:[{img:'World War I',say:'Всю войну моторы Майбаха поднимали в небо цеппелины и самолёты. В 1919 году Версальский договор запрещает Германии строить авиамоторы.'},
       {img:'Hyperinflation in the Weimar Republic',say:'Марка тает, и многим заводам Германии нечем платить рабочим. Заказов на авиамоторы больше не будет.'},
       {who:'Карл Майбах',line:'Мы умеем делать лучшие моторы в Германии. Если их не берут другие, построим автомобиль сами.'},
       {who:'Вильгельм Майбах',line:'Тогда пусть это будет машина без компромиссов. Такая, чтобы не стыдно было написать на ней нашу фамилию.'}],
   q:'Как пережить мир без авиамоторов?',
   o:[{t:'Строить свой роскошный автомобиль',fx:{cash:-1500,seg:{lux:[1.12,36]},b:{quality:[1.04,36]}},res:'В 1921 году на выставке в Берлине показывают первый «Майбах» — огромный, тихий и очень дорогой. С тех пор эта фамилия стоит на самых роскошных машинах Германии.'},
      {t:'Делать моторы для судов и поездов',fx:{cash:1200,seg:{truck:[1.08,24]},b:{lineCap:[1.05,24]}},res:'Тяжёлые моторы для судов и мотовагонов расходятся по заказам. Работа есть, хотя слава роскошных машин достаётся другим.'},
      {t:'Продавать моторы другим заводам',fx:{cash:800,rep:-1,b:{matCost:[0.94,24]}},res:'Моторы Майбаха встают под капоты чужих марок. Денег меньше, чем хотелось бы, зато станки не простаивают.'}]},
  {id:'maybach7',t:'Король конструкторов',y:1929,when:'finale',
   sc:[{img:'LZ 127 Graf Zeppelin',say:'Август 1929 года. Дирижабль «Граф Цеппелин» облетает земной шар за двадцать один день. Все пять его моторов построил завод Майбахов.'},
       {say:'В Токио и Лос-Анджелесе корабль встречают ликующие толпы.'},
       {img:'Wilhelm Maybach',say:'Восьмидесятитрёхлетний Вильгельм Майбах читает газеты в Штутгарте. На заводе сына уже готов автомобиль с мотором в двенадцать цилиндров.'},
       {who:'Карл Майбах',line:'Отец, тебя называют королём конструкторов. Что нам строить дальше?'},
       {who:'Вильгельм Майбах',line:'То, что будет работать, когда нас уже не будет.'}],
   q:'Каким будет последний замысел Майбаха?',
   o:[{t:'Двенадцать цилиндров для лучших дорог',fx:{cash:-1500,rep:3,seg:{lux:[1.15,24]}},res:'Роскошные «Майбахи» с двенадцатицилиндровым мотором станут легендой. Двадцать девятого декабря 1929 года Вильгельма Майбаха не стало.'},
      {t:'Моторы для скорых поездов',fx:{cash:1500,rep:2,b:{lineCap:[1.05,24]}},res:'Через несколько лет моторы Майбаха помчат скорый поезд из Берлина в Гамбург. Сам Вильгельм Майбах умер двадцать девятого декабря 1929 года.'},
      {t:'Учить молодых инженеров',fx:{cash:-500,rep:4,b:{devTime:[0.92,24]}},res:'До последних дней старик разбирает с учениками чертежи. Его школа — инженеры, которые построят моторы нового века.'}]}
];
SAGA.lanchester=[
  {id:'lanchester1',t:'С чистого листа',y:1895,when:'start',
   sc:[{img:'Frederick W. Lanchester',say:'Бирмингем, 1895 год. Инженер Фредерик Ланчестер с братьями Джорджем и Фрэнком строит автомобиль — не копию немецкой машины, а свой, с чистого листа.'},
       {img:'Red flag traffic laws',say:'Закон не на их стороне: самоходный экипаж должен ползти со скоростью пешехода, а впереди обязан идти человек.'},
       {who:'Джордж Ланчестер',line:'Фред, проще купить «Бенц» и переделать. Зачем изобретать всё заново?'},
       {who:'Фредерик Ланчестер',line:'Потому что немцы тоже ошибаются. Мотор должен работать без тряски, а машину надо рассчитывать, а не угадывать.'}],
   q:'Копировать чужую машину или строить свою?',
   o:[{t:'Строить всё с нуля',fx:{b:{quality:[1.06,36],devTime:[1.1,24]}},res:'Первая машина Ланчестеров выезжает на дороги в 1896 году — одна из самых первых в Британии. В ноябре того же года закон отменяет пешехода впереди, и путь открыт.'},
      {t:'Взять за образец немецкую машину',fx:{rep:-1,b:{devTime:[0.85,24]}},res:'Машина готова быстро и едет исправно. Но все видят в ней немку с английским акцентом.'},
      {t:'Сначала моторы для лодок',fx:{cash:700,b:{devTime:[1.05,18]}},res:'Моторы Ланчестера ставят на речные лодки, и заказы приносят деньги на опыты. Машина подождёт.'}]},
  {id:'lanchester2',t:'Станки прежде машин',y:1899,when:'firstProd',
   sc:[{img:'Lanchester Motor Company',say:'1899 год. Братья Ланчестеры основывают свою фирму. Но первой машины на продажу покупателям придётся ждать больше года.'},
       {say:'Фредерик требует, чтобы любая деталь одной машины подходила к другой. Для этого он сам проектирует станки, калибры и приспособления.'},
       {who:'Фрэнк Ланчестер',line:'Фред, покупатели ждут, акционеры ропщут, а ты всё строишь станки!'},
       {who:'Фредерик Ланчестер',line:'Зато потом любую деталь можно будет заказать по почте, и она подойдёт без напильника.'}],
   q:'Сначала станки или сразу машины?',
   o:[{t:'Сначала станки и калибры',fx:{cash:-1000,b:{quality:[1.05,36],lineCap:[1.05,36],devTime:[1.1,12]}},res:'Выпуск начинается поздно, зато «Ланчестер» становится одной из самых точных машин своего времени. Детали и правда подходят без подгонки.'},
      {t:'Собирать вручную, как все',fx:{cash:1000,b:{quality:[0.95,24],devTime:[0.92,12]}},res:'Машины идут к покупателям быстрее. Правда, каждую деталь механики подгоняют напильником.'}]},
  {id:'lanchester3',t:'Тысяча миль',y:1900,when:'firstRace',
   sc:[{say:'Весна 1900 года. Автомобильный клуб устраивает пробег на тысячу миль — от Лондона до Эдинбурга и обратно, через перевалы и вересковые пустоши.'},
       {say:'Десятки машин три недели идут по дорогам Англии и Шотландии, а газеты каждый день печатают отчёты.'},
       {img:'Frederick W. Lanchester',say:'Ланчестеры выставляют свою восьмисильную машину, уже отмеченную золотой медалью.'},
       {who:'Фрэнк Ланчестер',line:'Фред, у соперников моторы мощнее. Наша машина выдержит горы?'},
       {who:'Фредерик Ланчестер',line:'Выдержит. Мотор уравновешен, подвеска мягкая. Мы не будем гнаться — мы будем ехать.'}],
   q:'Как пройти тысячу миль?',
   o:[{t:'Ровно и бережно, без гонки',fx:{rep:3,mood:-2,b:{quality:[1.03,24]}},res:'Публика удивляется мягкому ходу машины из Бирмингема. О братьях Ланчестерах узнаёт вся Британия.'},
      {t:'Выжать из мотора всё',fx:{mood:6,b:{race:[0.03,24],quality:[0.97,18]}},res:'На подъёмах «Ланчестер» обходит машины помощнее, но механикам приходится чинить его каждую ночь.'},
      {t:'Посадить в машину репортёров',fx:{cash:-300,rep:2,b:{adEff:[1.08,24]}},res:'Газетчики трясутся на заднем сиденье и пишут о каждом подъёме. Машина идёт тяжелее, зато газеты полны её имени.'}]},
  {id:'lanchester4',t:'Под опекой кредиторов',y:1904,when:'y:1904',
   // 0.25: кредиторы приходят, только если фирме и правда нечем платить; выбор в фильме — это и решение газеты (lanchrcv)
   v:[{if:s=>!sagaPoor(s),t:'Меньше изобретений',
     sc:[{img:'Lanchester Motor Company',say:'1904 год. «Ланчестер» — одна из лучших машин страны: мягкая подвеска, тихий уравновешенный мотор, планетарная коробка передач и червячный привод задних колёс.'},
       {say:'В настоящей истории машин было слишком мало и они были слишком дороги: в 1904 году фирма не смогла платить по счетам и перешла под управление кредиторов.'},
       {say:'Ваша фирма по счетам платит. Но акционеры ропщут: каждую машину собирают вручную, и очередь за ней растёт.'},
       {who:'Председатель совета',line:'Мистер Ланчестер, нам нужно меньше изобретений и больше проданных машин.'},
       {who:'Фредерик Ланчестер',line:'Без изобретений эти машины ничем не лучше других. Их просто перестанут покупать.'}],
     q:'Как ответить акционерам?',
     o:[{t:'Нанять управляющего, остаться конструктором',fx:{b:{lineCap:[1.08,24],quality:[1.03,24],devTime:[1.06,24]}},res:'Новый управляющий наводит порядок в цехах, а Фредерик остаётся главным конструктором. Машин становится больше, а лучшими они остаются по-прежнему.'},
        {t:'Продать лицензии на патенты',fx:{cash:2500,rep:-1},res:'За лицензии на тормоза и коробку передач платят хорошо. Но свои лучшие идеи фирма теперь делит с соперниками.'},
        {t:'Упростить машину и снизить цену',fx:{cash:500,seg:{middle:[1.1,24],lux:[0.92,24]},b:{quality:[0.96,24]}},res:'Машина дешевеет и продаётся лучше, хотя знатоки ворчат: это уже не тот «Ланчестер».'}]}],
   sc:[{img:'Lanchester Motor Company',say:'1904 год. «Ланчестер» — одна из лучших машин страны: мягкая подвеска, тихий уравновешенный мотор, планетарная коробка передач и червячный привод задних колёс.'},
       {say:'Но машин слишком мало, и они слишком дороги. Фирма не может платить по счетам и переходит под управление кредиторов.'},
       {who:'Управляющий от кредиторов',line:'Мистер Ланчестер, нам нужно меньше изобретений и больше проданных машин.'},
       {who:'Фредерик Ланчестер',line:'Без изобретений эти машины ничем не лучше других. Их просто перестанут покупать.'}],
   q:'Как спасти фирму?',
   o:[{t:'Отдать управление, остаться конструктором',fx:{legal:'lanchrcv:lLanInv',b:{devTime:[1.08,24],quality:[1.03,24]}},res:'Фирму перестраивают, у руля новые люди, а Фредерик ещё несколько лет остаётся главным конструктором. Машины по-прежнему лучшие и по-прежнему дорогие.'},
      {t:'Продать патенты',fx:{cash:2500,legal:'lanchrcv:',b:{devTime:[1.08,24]}},res:'За патенты на тормоза и коробку передач платят хорошо. Но свои лучшие идеи фирма теперь делит с соперниками.'},
      {t:'Упростить машину и снизить цену',fx:{cash:500,legal:'lanchrcv:',seg:{middle:[1.1,24],lux:[0.92,24]},b:{quality:[0.96,24]}},res:'Машина дешевеет и продаётся лучше, хотя знатоки ворчат: это уже не тот «Ланчестер».'}]},
  {id:'lanchester5',t:'Теория крыла',y:1908,when:['y:1908','sold:500'],
   sc:[{img:'Wilbur Wright',say:'1908 год. Уилбур Райт летает над Францией, и мир бредит аэропланами.'},
       {say:'А Ланчестер давно рассчитал, как держит самолёт крыло. Ещё в 1897 году научное общество отказалось печатать его статью — теперь выходит его двухтомник «Воздушный полёт».'},
       {img:'Daimler Motor Company',say:'Правительство зовёт его в комитет по воздухоплаванию, а фирма «Даймлер» из Ковентри — в консультанты.'},
       {who:'Джордж Ланчестер',line:'Фред, нашей фирме нужен конструктор, который думает о машинах, а не о крыльях.'}],
   q:'Кому чертить новые «Ланчестеры»?',
   o:[{t:'Отдать чертёжную доску Джорджу',fx:{rep:1,b:{devTime:[0.9,24],quality:[0.98,24]}},res:'С 1909 года Фредерик работает на «Даймлер» и на авиацию, а Джордж становится главным конструктором «Ланчестера». Его машины будут выпускать до конца эпохи.'},
      {t:'Остаться главным конструктором',fx:{b:{quality:[1.05,36],devTime:[1.1,24]}},res:'Фредерик разрывается между машинами и аэропланами. Каждый новый «Ланчестер» — шедевр, но ждать его приходится долго.'},
      {t:'Строить аэропланы',fx:{cash:-1000,rep:3,b:{race:[0.02,24]}},res:'В мастерской появляется крыло, рассчитанное по новой теории. Публика в восторге, а гоночные машины фирмы становятся обтекаемыми.'}]},
  {id:'lanchester6',t:'Броневики',y:1914,when:'war',
   sc:[{img:'World War I',say:'Август 1914 года. Британия вступает в войну, и завод Ланчестеров в Бирмингеме переходит на военные заказы.'},
       {say:'На шасси «Ланчестера» ставят броню и пулемётную башню. Броневики уходят на фронт, а потом и в Россию — на Кавказ, в Румынию и Галицию.'},
       {say:'А Фредерик описывает войну формулами. Его закон квадратов гласит: сила армии растёт как квадрат её численности.'},
       {who:'Фредерик Ланчестер',line:'Будущие войны решит воздух. Авиация — это четвёртый род войск.'}],
   q:'Что строить в годы войны?',
   o:[{t:'Броневики для Адмиралтейства',fx:{cash:1800,seg:{truck:[1.1,24],lux:[0.9,24]},b:{quality:[1.03,24]}},res:'Броневики «Ланчестер» проходят тысячи километров по бездорожью. После войны о надёжности марки знают даже генералы.'},
      {t:'Работать на авиацию',fx:{cash:1000,rep:2,b:{devTime:[0.92,24]}},res:'Фредерик считает крылья и винты для комитета по воздухоплаванию, а инженеры завода учатся у авиации лёгкости и точности.'},
      {t:'Беречь мастеров для мирных машин',fx:{cash:-800,rep:1,b:{workerEff:[1.06,36]}},res:'Лучшие мастера остаются у станков. После войны «Ланчестер» быстрее других вернётся к роскошным машинам.'}]},
  {id:'lanchester7',t:'Последний расчёт',y:1929,when:'finale',
   sc:[{img:'Wall Street crash of 1929',say:'1929 год. Крах на американской бирже докатывается до Британии. Богатые клиенты откладывают покупку дорогих машин.'},
       {img:'Frederick W. Lanchester',say:'Фредерику Ланчестеру шестьдесят. Он член Королевского общества, автор множества патентов и теории, по которой летают самолёты.'},
       {say:'Его фамилия стоит на радиаторах, но фирмой он давно не руководит. Брат Джордж чертит для неё роскошные машины с восьмицилиндровыми моторами.'},
       {who:'Джордж Ланчестер',line:'Фред, дорогие машины сейчас никто не берёт. Может, пора искать сильного союзника?'},
       {who:'Фредерик Ланчестер',line:'Главное, чтобы под капотом осталась честная инженерия. Остальное — вопрос вывески.'}],
   q:'Как встретить трудные времена?',
   o:[{t:'Продать фирму большому концерну',fx:{cash:3000,rep:-2},res:'В 1931 году «Ланчестер» покупает концерн «Би-эс-эй», владелец «Даймлера». Марка проживёт ещё двадцать с лишним лет, но уже как младшая сестра «Даймлера».'},
      {t:'Остаться верными качеству',fx:{cash:-1500,rep:3,seg:{lux:[1.08,24]},b:{quality:[1.04,24]}},res:'Покупателей мало, но они не изменяют марке. Фредерик гордится: его идеи — дисковые тормоза и уравновешенный мотор — переживут эпоху.'},
      {t:'Сделать машину подешевле',fx:{cash:500,seg:{middle:[1.1,24],lux:[0.92,24]},b:{quality:[0.97,24]}},res:'Небольшой «Ланчестер» для среднего класса продаётся неплохо, но старые клиенты ворчат.'}]}
];
